/bin/zsh -lc "mkdir -p specs/hal-engine-tool-input-validation && cat > src/orchestration/tools/registry.acceptance.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

const definition = {
  name: 'weather',
  description: 'Get a forecast',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}, unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
    required: ['location'],
  },
};

// specs/hal-engine-tool-input-validation/spec.md#1
it('rejects invalid input and passes valid input unchanged', async () => {
  const registry = new ToolRegistry();
  const received: Record<string, unknown>[] = [];
  registry.register(definition, async input => {
    received.push(input);
    return 'forecast';
  });
  const missing = await registry.execute('weather', {});
  const wrongType = await registry.execute('weather', {location: 123456789});
  const wrongEnum = await registry.execute('weather', {location: 'Berlin', unit: 'kelvin'});
  const valid = {location: 'Berlin', unit: 'celsius', extra: 'preserved'};
  const result = await registry.execute('weather', valid);

  expect(missing.result).toMatch(/location.*required|required.*location/i);
  expect(wrongType.result).toMatch(/location.*string|string.*location/i);
  expect(wrongType.result).not.toContain('123456789');
  expect(wrongEnum.result).toMatch(/unit.*(enum|allowed)|(enum|allowed).*unit/i);
  expect(result.result).toBe('forecast');
  expect(received).toEqual([valid]);
});

// specs/hal-engine-tool-input-validation/spec.md#2
it('rejects an invalid static schema during registration with the tool name', () => {
  const registry = new ToolRegistry();
  expect(() => registry.register({...definition, inputSchema: {type: 'not-a-type'}}, async () => 'forecast')).toThrow(
    /weather/i
  );
});

// specs/hal-engine-tool-input-validation/spec.md#3
it('validates each call against the current dynamic schema', async () => {
  const registry = new ToolRegistry();
  let required = 'location';
  const received: Record<string, unknown>[] = [];
  registry.register(
    () => ({...definition, inputSchema: {...definition.inputSchema, required: [required]}}),
    async input => {
      received.push(input);
      return 'forecast';
    }
  );
  const first = await registry.execute('weather', {unit: 'celsius'});
  required = 'unit';
  const second = await registry.execute('weather', {location: 'Berlin'});
  const valid = {location: 'Berlin', unit: 'celsius'};
  await registry.execute('weather', valid);

  expect(first.result).toMatch(/location.*required|required.*location/i);
  expect(second.result).toMatch(/unit.*required|required.*unit/i);
  expect(received).toEqual([valid]);
});
EOF
cat > specs/hal-engine-tool-input-validation/spec.md <<'EOF'
# Tool input validation

| Field  | Value |
| ------ | ----- |
| Issue  | re-cinq/HALEngine#37 |
| Status | Draft |

Tool input is validated against the registered JSON Schema before an executor is called.

## Contract

1. Required properties, types and enums are enforced; a rejected call returns a result describing the property and constraint without its value, while valid input including extra properties reaches the executor unchanged. ([validated by: rejects invalid input and passes valid input unchanged](../../src/orchestration/tools/registry.acceptance.test.ts#L15))
2. An invalid static schema fails at registration with the tool name. ([validated by: rejects an invalid static schema during registration with the tool name](../../src/orchestration/tools/registry.acceptance.test.ts#L37))
3. A function-valued definition is validated against the schema resolved for each call. ([validated by: validates each call against the current dynamic schema](../../src/orchestration/tools/registry.acceptance.test.ts#L45))
EOF
cat > .lore/dod.md <<'EOF'
# Definition of Done

> "'`ToolRegistry.execute` looks a tool up, logs the input'"'s key names, and calls the executor
> without ever checking the declared "'`inputSchema` (`src/orchestration/tools/registry.ts`).

**Strategy: `direct`** — `ToolRegistry.register` and `execute` expose the real registration and execution boundary directly.

## Done when these pass

- [ ] **rejects invalid input and passes valid input unchanged** — Required, type and enum violations return useful, value-free errors without invoking the executor; valid extra properties pass through unchanged.
  `src/orchestration/tools/registry.acceptance.test.ts`
- [ ] **rejects an invalid static schema during registration with the tool name** — Invalid static schemas fail at startup with the tool identified.
  `src/orchestration/tools/registry.acceptance.test.ts`
- [ ] **validates each call against the current dynamic schema** — Dynamic definitions use the current schema for each invocation.
  `src/orchestration/tools/registry.acceptance.test.ts`

## Facets

- [ ] Compile static schemas at registration and cache dynamic schemas by resolved object; use a runtime JSON Schema dependency.
- [ ] Return value-free property and constraint errors before execution, without coercion, defaults or rejecting extra keys; keep unknown tool errors unchanged.
- [ ] Verify rejection logs omit input values and the orchestrator feeds the result back for a corrected retry within the existing round limit.
- [ ] Update the named documentation, migration note, minor version and changelog as specified in the ticket.

## Out of scope

- Tool output validation, authorization, execution retries, timeouts, rate limits and changing unknown-tool handling.
EOF
